// Flatten n8n's error payload into one decision line, so a failure lands in the same log
// the dashboard already reads. A failed night is a fact about the night.

const execution = $json.execution || {};
const workflow = $json.workflow || {};
const error = execution.error || $json.error || {};
const lastNode = execution.lastNodeExecuted || error.node || 'unknown node';

return {
  json: {
    stage: 'workflow_error',
    decision: 'failed',
    headline: `${workflow.name || 'a workflow'} stopped at ${lastNode}`,
    merchant_id: 'tea_stall_01',
    source: 'n8n',
    detail: {
      workflow_id: workflow.id || null,
      workflow_name: workflow.name || null,
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      last_node: lastNode,
      message: error.message || String(error) || 'no message',
      retry_of: execution.retryOf || null,
      mode: execution.mode || null,
    },
  },
};
